56	void MetalinkMetalinkParserState::beginElement(
57	    MetalinkParserStateMachine* psm, const char* localname, const char* prefix,
58	    const char* nsUri, const std::vector<XmlAttr>& attrs)
59	{
60	  if (checkNsUri(nsUri) && strcmp(localname, "files") == 0) {
61	    psm->setFilesState();
62	  }
