68	void FilesMetalinkParserState::beginElement(MetalinkParserStateMachine* psm,
69	                                            const char* localname,
70	                                            const char* prefix,
71	                                            const char* nsUri,
72	                                            const std::vector<XmlAttr>& attrs)
73	{
74	  if (checkNsUri(nsUri) && strcmp(localname, "file") == 0) {
75	    psm->setFileState();
76	    auto itr = findAttr(attrs, "name", METALINK3_NAMESPACE_URI);
77	    if (itr != attrs.end()) {
78	      std::string name((*itr).value, (*itr).valueLength);
79	      if (name.empty() || util::detectDirTraversal(name)) {
80	        return;
81	      }
82	      psm->newEntryTransaction();
83	      psm->setFileNameOfEntry(name);
84	    }
85	  }
86	  else {
87	    psm->setSkipTagState();
88	  }
89	}
