91	void FileMetalinkParserState::beginElement(MetalinkParserStateMachine* psm,
92	                                           const char* localname,
93	                                           const char* prefix,
94	                                           const char* nsUri,
95	                                           const std::vector<XmlAttr>& attrs)
96	{
97	  if (!checkNsUri(nsUri)) {
98	    psm->setSkipTagState();
99	  }
100	  else if (strcmp(localname, "size") == 0) {
101	    psm->setSizeState();
102	  }
103	  else if (strcmp(localname, "version") == 0) {
104	    psm->setVersionState();
105	  }
106	  else if (strcmp(localname, "language") == 0) {
107	    psm->setLanguageState();
108	  }
109	  else if (strcmp(localname, "os") == 0) {
110	    psm->setOSState();
111	  }
112	  else if (strcmp(localname, "verification") == 0) {
113	    psm->setVerificationState();
114	  }
115	  else if (strcmp(localname, "resources") == 0) {
116	    psm->setResourcesState();
117	    int maxConnections;
118	    auto itr = findAttr(attrs, "maxconnections", METALINK3_NAMESPACE_URI);
119	    if (itr == attrs.end()) {
120	      maxConnections = -1;
121	    }
122	    else {
123	      if (!util::parseIntNoThrow(
124	              maxConnections, std::string((*itr).value, (*itr).valueLength)) ||
125	          maxConnections <= 0) {
126	        maxConnections = -1;
127	      }
128	    }
129	    psm->setMaxConnectionsOfEntry(maxConnections);
130	  }
131	  else {
132	    psm->setSkipTagState();
133	  }
134	}
