183	void VerificationMetalinkParserState::beginElement(
184	    MetalinkParserStateMachine* psm, const char* localname, const char* prefix,
185	    const char* nsUri, const std::vector<XmlAttr>& attrs)
186	{
187	  if (!checkNsUri(nsUri)) {
188	    psm->setSkipTagState();
189	  }
190	  else if (strcmp(localname, "hash") == 0) {
191	    psm->setHashState();
192	    auto itr = findAttr(attrs, "type", METALINK3_NAMESPACE_URI);
193	    if (itr == attrs.end()) {
194	      return;
195	    }
196	    else {
197	      psm->newChecksumTransaction();
198	      psm->setTypeOfChecksum(std::string((*itr).value, (*itr).valueLength));
199	    }
200	  }
201	  else if (strcmp(localname, "pieces") == 0) {
202	    psm->setPiecesState();
203	    uint32_t length;
204	    {
205	      auto itr = findAttr(attrs, "length", METALINK3_NAMESPACE_URI);
206	      if (itr == attrs.end()) {
207	        return;
208	      }
209	      else {
210	        if (!util::parseUIntNoThrow(
211	                length, std::string((*itr).value, (*itr).valueLength))) {
212	          return;
213	        }
214	      }
215	    }
216	    std::string type;
217	    {
218	      auto itr = findAttr(attrs, "type", METALINK3_NAMESPACE_URI);
219	      if (itr == attrs.end()) {
220	        return;
221	      }
222	      else {
223	        type.assign((*itr).value, (*itr).valueLength);
224	      }
225	    }
226	    psm->newChunkChecksumTransaction();
227	    psm->setLengthOfChunkChecksum(length);
228	    psm->setTypeOfChunkChecksum(type);
229	  }
230	  else if (strcmp(localname, "signature") == 0) {
231	    psm->setSignatureState();
232	    auto itr = findAttr(attrs, "type", METALINK3_NAMESPACE_URI);
233	    if (itr == attrs.end()) {
234	      return;
235	    }
236	    else {
237	      psm->newSignatureTransaction();
238	      psm->setTypeOfSignature(std::string((*itr).value, (*itr).valueLength));
239	      auto itr = findAttr(attrs, "file", METALINK3_NAMESPACE_URI);
240	      if (itr != attrs.end()) {
241	        std::string file((*itr).value, (*itr).valueLength);
242	        if (!util::detectDirTraversal(file)) {
243	          psm->setFileOfSignature(file);
244	        }
245	      }
246	    }
247	  }
248	  else {
249	    psm->setSkipTagState();
250	  }
251	}
252	
253	void HashMetalinkParserState::endElement(MetalinkParserStateMachine* psm,
254	                                         const char* localname,
255	                                         const char* prefix, const char* nsUri,
256	                                         std::string characters)
257	{
258	  psm->setHashOfChecksum(std::move(characters));
259	  psm->commitChecksumTransaction();
260	}
261	
262	void PiecesMetalinkParserState::beginElement(MetalinkParserStateMachine* psm,
263	                                             const char* localname,
264	                                             const char* prefix,
265	                                             const char* nsUri,
266	                                             const std::vector<XmlAttr>& attrs)
267	{
268	  if (checkNsUri(nsUri) && strcmp(localname, "hash") == 0) {
269	    psm->setPieceHashState();
270	    auto itr = findAttr(attrs, "piece", METALINK3_NAMESPACE_URI);
271	    if (itr == attrs.end()) {
272	      psm->cancelChunkChecksumTransaction();
273	    }
274	    else {
275	      uint32_t idx;
276	      if (util::parseUIntNoThrow(
277	              idx, std::string((*itr).value, (*itr).valueLength))) {
278	        psm->createNewHashOfChunkChecksum(idx);
279	      }
280	      else {
281	        psm->cancelChunkChecksumTransaction();
282	      }
283	    }
284	  }
285	  else {
286	    psm->setSkipTagState();
287	  }
288	}
289	
290	void PiecesMetalinkParserState::endElement(MetalinkParserStateMachine* psm,
291	                                           const char* localname,
292	                                           const char* prefix,
293	                                           const char* nsUri,
294	                                           std::string characters)
295	{
296	  psm->commitChunkChecksumTransaction();
297	}
298	
299	void PieceHashMetalinkParserState::endElement(MetalinkParserStateMachine* psm,
300	                                              const char* localname,
301	                                              const char* prefix,
302	                                              const char* nsUri,
303	                                              std::string characters)
304	{
305	  psm->setMessageDigestOfChunkChecksum(std::move(characters));
306	  psm->addHashOfChunkChecksum();
307	}
308	
309	void SignatureMetalinkParserState::endElement(MetalinkParserStateMachine* psm,
310	                                              const char* localname,
311	                                              const char* prefix,
312	                                              const char* nsUri,
313	                                              std::string characters)
314	{
315	  psm->setBodyOfSignature(std::move(characters));
316	  psm->commitSignatureTransaction();
317	}
318	
319	void ResourcesMetalinkParserState::beginElement(
320	    MetalinkParserStateMachine* psm, const char* localname, const char* prefix,
321	    const char* nsUri, const std::vector<XmlAttr>& attrs)
322	{
323	  if (!checkNsUri(nsUri)) {
324	    psm->setSkipTagState();
325	  }
326	  else if (strcmp(localname, "url") == 0) {
327	    psm->setURLState();
328	    std::string type;
329	    {
330	      auto itr = findAttr(attrs, "type", METALINK3_NAMESPACE_URI);
331	      if (itr == attrs.end()) {
332	        return;
333	      }
334	      type.assign((*itr).value, (*itr).valueLength);
335	    }
336	    std::string location;
337	    {
338	      auto itr = findAttr(attrs, "location", METALINK3_NAMESPACE_URI);
339	      if (itr != attrs.end()) {
340	        location.assign((*itr).value, (*itr).valueLength);
341	      }
342	    }
343	    int preference;
344	    {
345	      auto itr = findAttr(attrs, "preference", METALINK3_NAMESPACE_URI);
346	      if (itr == attrs.end()) {
347	        preference = MetalinkResource::getLowestPriority();
348	      }
349	      else if (util::parseIntNoThrow(
350	                   preference, std::string((*itr).value, (*itr).valueLength)) &&
351	               preference >= 0) {
352	        // In Metalink3Spec, highest preference value is 100.  We
353	        // use Metalink4Spec priority unit system in which 1 is
354	        // highest.
355	        preference = 101 - preference;
356	      }
357	      else {
358	        preference = MetalinkResource::getLowestPriority();
359	      }
360	    }
361	    int maxConnections;
362	    {
363	      auto itr = findAttr(attrs, "maxconnections", METALINK3_NAMESPACE_URI);
364	      if (itr == attrs.end()) {
365	        maxConnections = -1;
366	      }
367	      else if (!util::parseIntNoThrow(
368	                   maxConnections,
369	                   std::string((*itr).value, (*itr).valueLength)) ||
370	               maxConnections <= 0) {
371	        maxConnections = -1;
372	      }
373	    }
374	    psm->newResourceTransaction();
375	    psm->setTypeOfResource(type);
376	    psm->setLocationOfResource(location);
377	    psm->setPriorityOfResource(preference);
378	    psm->setMaxConnectionsOfResource(maxConnections);
379	  }
380	  else {
381	    psm->setSkipTagState();
382	  }
383	}
384	
385	void URLMetalinkParserState::endElement(MetalinkParserStateMachine* psm,
386	                                        const char* localname,
387	                                        const char* prefix, const char* nsUri,
388	                                        std::string characters)
389	{
390	  psm->setURLOfResource(std::move(characters));
391	  psm->commitResourceTransaction();
392	}
393	
394	} // namespace aria2
