199	  if (type == "ftp" || type == "sftp") {
200	    tResource_->type = MetalinkResource::TYPE_FTP;
201	  }
202	  else if (type == "http") {
203	    tResource_->type = MetalinkResource::TYPE_HTTP;
204	  }
205	  else if (type == "https") {
206	    tResource_->type = MetalinkResource::TYPE_HTTPS;
207	  }
208	  else if (type == "bittorrent" || type == "torrent") {
209	    // "torrent" is Metalink4Spec
