46	bool parseFile(const std::string& filename, ParserStateMachine* psm)
47	{
48	  int fd;
49	  if (filename == DEV_STDIN) {
50	    fd = STDIN_FILENO;
51	  }
52	  else {
53	    while ((fd = a2open(utf8ToWChar(filename).c_str(), O_BINARY | O_RDONLY,
