    assert(pattrs[i]);
    xmlAttr.localname = pattrs[i];
    if (pattrs[i + 1]) {
      xmlAttr.prefix = pattrs[i + 1];
    }
    if (attrs[i + 2]) {
      xmlAttr.nsUri = pattrs[i + 2];
    }
    xmlAttr.value = pattrs[i + 3];
    xmlAttr.valueLength = pattrs[i + 4] - xmlAttr.value;
    xmlAttrs.push_back(xmlAttr);
