51	void splitNsName(const char** localname, const char** nsUri, const char* src)
52	{
53	  const char* sep = strchr(src, '\t');
54	  if (sep) {
55	    *localname = sep + 1;
56	    size_t nsUriLen = sep - src;
57	    auto temp = new char[nsUriLen + 1];
58	    memcpy(temp, src, nsUriLen);
59	    temp[nsUriLen] = '\0';
60	    *nsUri = temp;
61	  }
62	  else {
