72	  std::vector<XmlAttr> xmlAttrs;
73	  if (attrs) {
74	    const char** p = attrs;
75	    while (*p) {
76	      XmlAttr xa;
77	      const char* attrNsName = *p++;
78	      if (!*p) {
79	        break;
80	      }
81	      splitNsName(&xa.localname, &xa.nsUri, attrNsName);
82	      const char* value = *p++;
83	      xa.value = value;
84	      xa.valueLength = strlen(value);
85	      xmlAttrs.push_back(xa);
86	    }
87	  }
88	  const char* localname = nullptr;
89	  const char* prefix = nullptr;
90	  const char* nsUri = nullptr;
91	  splitNsName(&localname, &nsUri, nsName);
92	  sd->psm->beginElement(localname, prefix, nsUri, xmlAttrs);
93	  delete[] nsUri;
