56	std::vector<std::unique_ptr<MetalinkEntry>>
57	query(const std::shared_ptr<Metalinker>& metalinker, const Option* option)
58	{
59	  return metalinker->queryEntry(option->get(PREF_METALINK_VERSION),
60	                                option->get(PREF_METALINK_LANGUAGE),
61	                                option->get(PREF_METALINK_OS));
62	}
