65	
66	std::vector<std::unique_ptr<MetalinkEntry>>
67	parseAndQuery(const std::string& filename, const Option* option,
68	              const std::string& baseUri)
69	{
70	  return query(parseFile(filename, baseUri), option);
71	}
72	
73	std::vector<std::unique_ptr<MetalinkEntry>>
74	parseAndQuery(BinaryStream* bs, const Option* option,
75	              const std::string& baseUri)
76	{
77	  return query(parseBinaryStream(bs, baseUri), option);
78	}
79	
80	std::vector<std::pair<std::string, std::vector<MetalinkEntry*>>>
81	groupEntryByMetaurlName(
82	    const std::vector<std::unique_ptr<MetalinkEntry>>& entries)
83	{
84	  std::vector<std::pair<std::string, std::vector<MetalinkEntry*>>> result;
85	  for (auto& entry : entries) {
86	    if (entry->metaurls.empty()) {
87	      // std::pair<std::string, std::vector<MetalinkEntry*>> p;
88	      // p.second.push_back(entry.get());
89	      result.push_back({"", {entry.get()}});
90	    }
91	    else {
92	      auto i = std::begin(result);
93	      if (entry->metaurls[0]->name.empty() || !entry->sizeKnown) {
94	        i = std::end(result);
95	      }
96	      for (; i != std::end(result); ++i) {
97	        if ((*i).first == entry->metaurls[0]->url &&
98	            !(*i).second[0]->metaurls[0]->name.empty()) {
