84	  CPPUNIT_ASSERT_EQUAL(std::string("0beec7b5ea3f0fdbc95d0dd47f3c5bc275da8a33"),
85	                       util::toHex(e->checksum->getDigest()));
86	  CPPUNIT_ASSERT(e->checksum);
87	  CPPUNIT_ASSERT_EQUAL(std::string("sha-1"), e->checksum->getHashType());
88	  CPPUNIT_ASSERT(e->chunkChecksum);
