94	    CPPUNIT_ASSERT_EQUAL(
95	        std::string(
96	            "0245178074fd042e19b7c3885b360fc21064b30e73f5626c7e3b005d048069c5"),
97	        util::toHex(e->chunkChecksum->getPieceHash(0)));
98	    CPPUNIT_ASSERT_EQUAL(
99	        std::string(
100	            "487ba2299be7f759d7c7bf6a4ac3a32cee81f1bb9332fc485947e32918864fb2"),
101	        util::toHex(e->chunkChecksum->getPieceHash(1)));
102	    CPPUNIT_ASSERT_EQUAL(
103	        std::string(
104	            "37290d74ac4d186e3a8e5785d259d2ec04fac91ae28092e7620ec8bc99e830aa"),
105	        util::toHex(e->chunkChecksum->getPieceHash(2)));
106	  }
107	  else {
108	    CPPUNIT_ASSERT_EQUAL(std::string("sha-1"), e->chunkChecksum->getHashType());
109	    CPPUNIT_ASSERT_EQUAL(262144, e->chunkChecksum->getPieceLength());
110	    CPPUNIT_ASSERT_EQUAL((size_t)3, e->chunkChecksum->countPieceHash());
111	    CPPUNIT_ASSERT_EQUAL(
112	        std::string("5bd9f7248df0f3a6a86ab6c95f48787d546efa14"),
113	        util::toHex(e->chunkChecksum->getPieceHash(0)));
114	    CPPUNIT_ASSERT_EQUAL(
115	        std::string("9413ee70957a09d55704123687478e07f18c7b29"),
116	        util::toHex(e->chunkChecksum->getPieceHash(1)));
117	    CPPUNIT_ASSERT_EQUAL(
118	        std::string("44213f9f4d59b557314fadcd233232eebcac8012"),
119	        util::toHex(e->chunkChecksum->getPieceHash(2)));
120	  }
121	  CPPUNIT_ASSERT(e->getSignature());
122	  CPPUNIT_ASSERT_EQUAL(std::string("application/pgp-signature"),
123	                       e->getSignature()->getType());
124	  CPPUNIT_ASSERT_EQUAL(std::string("a signature"),
125	                       e->getSignature()->getBody());
126	
127	  CPPUNIT_ASSERT_EQUAL((size_t)2, e->resources.size());
128	  auto& r = e->resources[0];
129	  CPPUNIT_ASSERT_EQUAL(std::string("ftp://ftp.example.com/example.ext"),
130	                       r->url);
131	  CPPUNIT_ASSERT_EQUAL(std::string("de"), r->location);
132	  CPPUNIT_ASSERT_EQUAL(1, r->priority);
133	  CPPUNIT_ASSERT_EQUAL(std::string("ftp"),
